import { Router, type Request, type Response } from "express";
import { getAllDevices, getDeviceById, updateDeviceState } from "../db/devices-table";
import { getSchedules } from "../db/schedules-table";

export const router = Router();

router.get("/run-scheduled-rules", async (req: Request, res: Response) => {
  const schedules = getSchedules();
  const currentTime = new Date().toISOString();

  for (const schedule of schedules) {
    if (schedule.trigger_time === currentTime) {
      const device = getDeviceById(schedule.device_id);
      if (device) {
        updateDeviceState(device.id, schedule.action);
      }
    }
  }

  res.status(200).send({ message: "Scheduled rules run successfully." });
});

