router.get("/timesheets/:employeeId", (req: Request, res: Response) => {
  const employeeId = Number(req.params.employeeId);
  const clockEvents = getClockEventsByEmployeeId(employeeId);
  const timesheet = calculateTimesheet(clockEvents);
  res.json(timesheet);
});

function calculateTimesheet(clockEvents: ClockEvent[]): Record<string, number> {
  const timesheet: Record<string, number> = {};
  let currentWeekStart = new Date().setHours(0, 0, 0, 0);
  while (currentWeekStart < new Date()) {
    const weekEnd = new Date(currentWeekStart + 6 * 24 * 60 * 60 * 1000);
    const weekEvents = clockEvents.filter(event => {
      const eventDate = new Date(event.timestamp);
      return eventDate >= currentWeekStart && eventDate <= weekEnd;
    });
    const totalHours = weekEvents.reduce((sum, event, index) => {
      if (index % 2 === 0) return sum;
      const prevEvent = weekEvents[index - 1];
      const duration = new Date(event.timestamp).getTime() - new Date(prevEvent.timestamp).getTime();
      return sum + duration / (1000 * 60 * 60);
    }, 0);
    timesheet[new Date(currentWeekStart).toISOString().split("T")[0]] = totalHours;
    currentWeekStart = new Date(currentWeekStart + 7 * 24 * 60 * 60 * 1000);
  }
  return timesheet;
}

